import {localDate} from './core.js?v=4';
import {statistics,periodRange,shiftDay} from './statistics-core.js?v=5';
const $=id=>document.getElementById(id),format=n=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:2}).format(n);
const date=(day,short=false)=>new Intl.DateTimeFormat('de-DE',{day:'2-digit',month:'2-digit',...(short?{}:{year:'numeric'})}).format(new Date(day+'T12:00:00'));
const el=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e};
const svg=(tag,attrs={},text)=>{const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;return e};
export function createStatistics({getEntries,getDay}){
 const dialog=$('stats-dialog');let latest;
 function setPreset(){const kind=$('stats-period').value;$('stats-custom').hidden=kind!=='custom';$('stats-anchor-wrap').hidden=kind==='custom';$('stats-navigation').hidden=kind==='custom';$('stats-prev').disabled=kind==='custom';$('stats-next').disabled=kind==='custom';if(kind!=='custom'){const today=localDate(),anchor=$('stats-anchor').value||today;const range=periodRange(kind,anchor>today?today:anchor,today);$('stats-start').value=range.start;$('stats-end').value=range.end;$('stats-next').disabled=periodRange(kind,nextAnchor(1),today).start>today}refresh()}
 function nextAnchor(direction){const kind=$('stats-period').value,anchor=$('stats-anchor').value||localDate();if(kind==='week')return shiftDay(anchor,7*direction);const d=new Date(anchor+'T12:00:00');d.setDate(1);if(kind==='month')d.setMonth(d.getMonth()+direction);else d.setFullYear(d.getFullYear()+direction);return localDate(d)}
 function choices(summary){const view=$('stats-view').value,select=$('stats-detail'),previous=select.value;const options=view==='drinks'?summary.drinks.map(d=>({value:'drink:'+d.name,name:d.name})):view==='nutrients'?summary.nutrients.map(n=>({value:'nutrient:'+n.id,name:n.name+' ('+n.unit+')'})):[];select.replaceChildren(...options.map(o=>{const option=el('option','',o.name);option.value=o.value;return option}));if(options.some(o=>o.value===previous))select.value=previous;select.disabled=!options.length;$('stats-detail-wrap').hidden=view==='total';return view==='total'?'volume':select.value||null}
 function table(container,headers,rows){container.replaceChildren();if(!rows.length){container.append(el('p','section-hint','Keine Mengenangaben für diesen Zeitraum.'));return}const table=el('table','stats-table'),thead=el('thead'),tr=el('tr');for(const h of headers){const th=el('th','',h);th.scope='col';tr.append(th)}thead.append(tr);const tbody=el('tbody');for(const cells of rows){const r=el('tr');cells.forEach((value,i)=>{const td=el(i?'td':'th');if(!i)td.scope='row';if(typeof value==='string')td.textContent=value;else td.append(value);r.append(td)});tbody.append(r)}table.append(thead,tbody);container.append(table)}
 function metricButton(name,view,value){const b=el('button','stats-metric-link',name);b.type='button';b.onclick=()=>{$('stats-view').value=view;refresh();$('stats-detail').value=value;refresh();$('stats-chart').scrollIntoView({block:'nearest',behavior:'smooth'})};return b}
 function tables(data){table($('stats-drinks-table'),['Getränkeart','Menge','Ø pro Tag'],data.drinks.map(d=>[metricButton(d.name,'drinks','drink:'+d.name),format(d.value)+' l',format(d.average)+' l']));table($('stats-nutrients-table'),['Inhaltsstoff','Erfasste Menge','Ø pro Tag','Angaben'],data.nutrients.map(n=>[metricButton(n.name,'nutrients','nutrient:'+n.id),format(n.value)+' '+n.unit,format(n.average)+' '+n.unit,n.known+' / '+n.relevant+' Einträge']));}
 function chart(data){
  const average=$('stats-mode').value==='average',values=data.buckets.map(b=>average?b.average:b.value),width=Math.max($('stats-chart').clientWidth||640,data.buckets.length*(data.aggregation==='week'?95:data.aggregation==='day'?28:52)+86),height=310,left=68,right=18,top=25,bottom=65,plotH=height-top-bottom,plotW=width-left-right,max=Math.max(...values.filter(v=>v!==null),0)||1,limit=max*1.12;
  const unit=data.total.unit+(average?'/Tag':''),title=data.total.name+' · '+(average?'Durchschnitt pro Tag':'Menge pro Abschnitt');$('stats-chart-title').textContent=title;$('stats-chart-unit').textContent=unit;
  const root=svg('svg',{viewBox:`0 0 ${width} ${height}`,width,height,role:'group','aria-label':title+' in '+unit});root.append(svg('title',{},title),svg('desc',{},'Die Balken zeigen '+(average?'Tagesdurchschnitte':'Summen')+'. Einzelwerte stehen auch in der Tabelle unter dem Diagramm.'));
  for(let i=0;i<=4;i++){const y=top+plotH-i*plotH/4;root.append(svg('line',{x1:left,x2:width-right,y1:y,y2:y,stroke:'#e1e9e5'}),svg('text',{x:left-9,y:y+4,'text-anchor':'end',class:'stats-axis'},format(limit*i/4)))}
  data.buckets.forEach((b,i)=>{const value=values[i],step=plotW/data.buckets.length,barWidth=Math.max(3,Math.min(42,step*.65)),x=left+i*step+(step-barWidth)/2,h=value===null?5:Math.max(1.5,value/limit*plotH),range=b.start===b.end?date(b.start):date(b.start)+' – '+date(b.end),text=range+': '+(value===null?'keine Mengenangaben':format(value)+' '+unit)+(b.partial&&value!==null?' (unvollständige Angaben)':'');
   const rect=svg('rect',{x,y:top+plotH-h,width:barWidth,height:h,rx:3,fill:value===null?'#c7d1ca':b.partial?'#80a89b':'#0b655c',class:'stats-bar',tabindex:0,role:'button','aria-label':text,'data-start':b.start,'data-value':value===null?'unknown':value});rect.append(svg('title',{},text));const show=()=>{$('stats-point').textContent=text};rect.onclick=show;rect.onfocus=show;rect.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();show()}};root.append(rect);
   let label=data.aggregation==='month'?new Intl.DateTimeFormat('de-DE',{month:'short',year:'2-digit'}).format(new Date(b.start+'T12:00:00')):data.aggregation==='week'?date(b.start,true)+'–'+date(b.end,true):date(b.start,true);root.append(svg('text',{x:left+(i+.5)*step,y:height-bottom+24,'text-anchor':'middle',class:'stats-axis'},label));
  });$('stats-chart').replaceChildren(root);$('stats-point').textContent='Balken antippen oder fokussieren, um den Wert anzuzeigen.';
  table($('stats-buckets-table'),['Abschnitt','Menge','Ø pro Tag','Tage'],data.buckets.map(b=>[b.start===b.end?date(b.start):date(b.start)+' – '+date(b.end),b.value===null?'Unbekannt':format(b.value)+' '+data.total.unit+(b.partial?' *':''),b.average===null?'Unbekannt':format(b.average)+' '+data.total.unit,String(b.days)]));
 }
 function refresh(){if(!dialog.open)return;try{
   const start=$('stats-start').value,end=$('stats-end').value;if(!start||!end)throw Error('Bitte Anfangs- und Enddatum wählen.');if(end>localDate())throw Error('Bitte einen Zeitraum bis spätestens heute wählen.');const base=statistics(getEntries(),{start,end,aggregation:$('stats-aggregation').value});const metric=choices(base);latest=metric?statistics(getEntries(),{start,end,aggregation:$('stats-aggregation').value,metric}):null;
   $('stats-error').hidden=true;$('stats-results').hidden=false;$('stats-range-label').textContent=date(start)+' – '+date(end);$('stats-days').textContent=base.days+' '+(base.days===1?'Tag':'Tage');$('stats-entries').textContent=base.entries+' '+(base.entries===1?'Eintrag':'Einträge');$('stats-denominator').textContent='Ø pro Tag = erfasste Menge ÷ '+base.days+' Kalendertage, einschließlich Tagen ohne Eintrag. Laufende Kalenderzeiträume enden heute.';
   tables(base);$('stats-chart-panel').hidden=!latest;$('stats-no-metric').hidden=!!latest;
   if(latest){$('stats-total-name').textContent=latest.total.name+' · erfasst';$('stats-total').textContent=latest.total.unknown?'—':format(latest.total.value)+' '+latest.total.unit;$('stats-average').textContent=latest.total.unknown?'—':format(latest.total.average)+' '+latest.total.unit+'/Tag';$('stats-coverage').textContent=latest.total.partial?`${latest.total.known} von ${latest.total.relevant} Einträgen mit Mengenangaben. Summen und Durchschnitte sind unvollständig; fehlende Werte sind nicht als null eingerechnet. Helle Balken: unvollständig; graue Markierung: unbekannt.`:'Auswertung aller erfassten Einträge. Historische Angaben und gegebenenfalls hinterlegte Richtwerte werden verwendet.';chart(latest)}else{$('stats-total-name').textContent='Erfasste Menge';$('stats-total').textContent='—';$('stats-average').textContent='—';$('stats-coverage').textContent='Für diesen Zeitraum sind keine Inhaltsstoffmengen hinterlegt.'}
  }catch(error){$('stats-error').textContent=error.message;$('stats-error').hidden=false;$('stats-results').hidden=true}}
 $('stats-open').onclick=()=>{const today=localDate();for(const id of ['stats-anchor','stats-start','stats-end'])$(id).max=today;$('stats-anchor').value=getDay()>today?today:getDay();dialog.showModal();setPreset()};
 $('stats-period').onchange=setPreset;$('stats-anchor').onchange=()=>{if(!$('stats-anchor').value||$('stats-anchor').value>localDate())$('stats-anchor').value=localDate();setPreset()};
 $('stats-prev').onclick=()=>{$('stats-anchor').value=nextAnchor(-1);setPreset()};$('stats-next').onclick=()=>{$('stats-anchor').value=nextAnchor(1);setPreset()};
 for(const id of ['stats-start','stats-end','stats-view','stats-detail','stats-aggregation','stats-mode'])$(id).onchange=refresh;
 window.addEventListener('resize',refresh);
 return {refresh};
}
